"""The MCP config Stage 2 hands to `claude -p` (T2.4, D9). No Docker.

Two properties carry this file. **One spawn shape:** the config is built from
`McpContainer.run_args()`, the same argv Stage 1 already spawns and asserts against, so Stage 2
cannot end up testing a differently-wired container than the stage that verified the wiring.
**The working tree, not a copy:** the docstring under test lives in `server.py` and the image
holds a copy of it, so every module of the repo is bind-mounted read-only over `/app` (D9).
Otherwise the Stage-2 loop — edit docstring, rerun — would grade the docstring of the last
build.

The mounted list is *derived* from the repo root, never enumerated. The Dockerfile's explicit
`COPY` list is the enumeration that has shipped a broken image twice by falling behind the
tree; a second list here would fall behind it the same way, and a new module missing from the
mount would be graded as its stale copy without anything looking wrong.
"""

from __future__ import annotations

import json
from pathlib import Path

import pytest
from harness.mcp_container import ImageRef
from stage2 import mcp_config

IMAGE = ImageRef(reference="gramps-remote-mcp:e2e-abcd1234", image_id="sha256:feed", leg="d")
REPO_ROOT = Path(__file__).resolve().parents[2]


@pytest.fixture(scope="module")
def entry() -> dict:
    return mcp_config.build(
        IMAGE,
        network="gwe2e-abcd1234-net",
        gramps_env={"GRAMPS_BASE_URL": "http://gwe2e-abcd1234-web:5000"},
        backup_dir=Path("/tmp/gwe2e-abcd1234/backup"),
        runid="abcd1234",
    )["mcpServers"]["gramps"]


def volumes(entry: dict) -> list[str]:
    args = entry["args"]
    return [args[index + 1] for index, item in enumerate(args) if item == "-v"]


def test_exactly_one_server_is_declared() -> None:
    config = mcp_config.build(IMAGE, network="net", gramps_env={}, backup_dir=Path("/b"))

    assert list(config["mcpServers"]) == ["gramps"]


def test_the_command_is_the_same_docker_spawn_stage_one_verifies(entry: dict) -> None:
    assert entry["command"] == "docker"
    assert entry["args"][:2] == ["run", "--rm"]
    assert "-i" in entry["args"], "stdio needs the container's stdin held open"


def test_the_image_is_pinned_by_id_not_by_tag(entry: dict) -> None:
    """A concurrent reaper sweeps `:e2e-*` by name and the release ritual re-points `:latest`."""
    assert entry["args"][-1] == IMAGE.image_id


def test_every_repo_module_is_mounted_read_only_over_the_image(entry: dict) -> None:
    mounted = volumes(entry)

    for module in sorted(REPO_ROOT.glob("*.py")):
        assert f"{module}:/app/{module.name}:ro" in mounted


def test_the_mount_list_is_derived_from_the_tree_not_enumerated(tmp_path: Path) -> None:
    """The anti-drift property: a fifth module appears without anybody editing a list."""
    for name in ("server.py", "gramps_client.py", "brand_new_module.py"):
        (tmp_path / name).write_text("", encoding="utf-8")

    mounted = volumes(
        mcp_config.build(
            IMAGE, network="net", gramps_env={}, backup_dir=Path("/b"), repo_root=tmp_path
        )["mcpServers"]["gramps"]
    )

    assert f"{tmp_path / 'brand_new_module.py'}:/app/brand_new_module.py:ro" in mounted


def test_a_non_module_at_the_repo_root_is_not_mounted(tmp_path: Path) -> None:
    (tmp_path / "server.py").write_text("", encoding="utf-8")
    (tmp_path / "README.md").write_text("", encoding="utf-8")

    mounted = volumes(
        mcp_config.build(
            IMAGE, network="net", gramps_env={}, backup_dir=Path("/b"), repo_root=tmp_path
        )["mcpServers"]["gramps"]
    )

    assert len(mounted) == 2, "the four modules are one mount each, plus the backup directory"


def test_the_backup_directory_is_mounted_writable_and_named(entry: dict) -> None:
    """`export_tree` writes into it and `import_file` reads from it — read-only would be a lie."""
    assert f"/tmp/gwe2e-abcd1234/backup:{mcp_config.BACKUP_TARGET}" in volumes(entry)

    environment = env_of(entry)
    assert environment["GRAMPS_BACKUP_DIR"] == mcp_config.BACKUP_TARGET


def env_of(entry: dict) -> dict[str, str]:
    args = entry["args"]
    pairs = [args[index + 1] for index, item in enumerate(args) if item == "-e"]
    return dict(pair.split("=", 1) for pair in pairs)


def test_the_destructive_tools_are_armed(entry: dict) -> None:
    """uc5 and uc20 are delete use cases; without the flag those tools do not exist at all."""
    assert env_of(entry)["GRAMPS_ENABLE_DESTRUCTIVE"] == "1"


def test_the_instance_credentials_are_passed_through(entry: dict) -> None:
    assert env_of(entry)["GRAMPS_BASE_URL"] == "http://gwe2e-abcd1234-web:5000"


def test_the_container_joins_the_instance_network(entry: dict) -> None:
    args = entry["args"]
    assert args[args.index("--network") + 1] == "gwe2e-abcd1234-net"


def test_the_container_carries_the_run_label(entry: dict) -> None:
    """The reaper filters on the label, so a Stage-2 container is not somebody's stray."""
    args = entry["args"]
    assert args[args.index("--label") + 1] == "gramps-e2e=abcd1234"


def test_the_config_is_written_as_json_and_reads_back(tmp_path: Path) -> None:
    path = mcp_config.write(
        tmp_path / "mcp.json",
        mcp_config.build(IMAGE, network="net", gramps_env={}, backup_dir=Path("/b")),
    )

    assert json.loads(path.read_text(encoding="utf-8"))["mcpServers"]["gramps"]["type"] == "stdio"
